package com.styleshop.order.model;
import jakarta.persistence.*;import java.math.BigDecimal;
@Entity @Table(name="cart_items",uniqueConstraints=@UniqueConstraint(columnNames={"username","productId"})) public class CartItem {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;private String username;private Long productId;private String name;private BigDecimal price;private String imageUrl;private int quantity=1;public Long getId(){return id;}public String getUsername(){return username;}public void setUsername(String v){username=v;}public Long getProductId(){return productId;}public void setProductId(Long v){productId=v;}public String getName(){return name;}public void setName(String v){name=v;}public BigDecimal getPrice(){return price;}public void setPrice(BigDecimal v){price=v;}public String getImageUrl(){return imageUrl;}public void setImageUrl(String v){imageUrl=v;}public int getQuantity(){return quantity;}public void setQuantity(int v){quantity=v;}}
